// <script>
   // <script>
(function () {
  try {
    /* 🛑 GLOBAL EXECUTION LOCK */
    var SCRIPT_ID = "rtg-geo-time-guard-01";
    if (window.__AFF_SCRIPT_LOADED === SCRIPT_ID) return;
    window.__AFF_SCRIPT_LOADED = SCRIPT_ID;

    var COOLDOWN_MINUTES = 30;
    var now = Date.now();

    /* 🔒 HARD COOLDOWN (30 MINUTES) */
    var lastRun = localStorage.getItem("aff_last_run_ts");
    if (lastRun && now - parseInt(lastRun, 10) < COOLDOWN_MINUTES * 60 * 1000) {
      return;
    }

    /* 🔐 SESSION LOCK – click counted only once per session */
    if (sessionStorage.getItem("aff_redirected") === "1") return;

    /* ❌ BLOCK EXISTING AFFILIATE / ADS TRAFFIC */
    var blockedParams = [
      "utm_source",
      "utm_medium",
      "utm_campaign",
      "awc",
      "gclid",
      "gbraid",
      "gad_campaignid",
      "sv1",
      "sv_campaign_id"
    ];

    var params = new URLSearchParams(window.location.search);
    if (blockedParams.some(p => params.has(p))) return;

    /* ⏱ IST TIME CHECK */
    function isAllowedISTTime() {
      var nowIST = new Date(
        new Date().toLocaleString("en-US", { timeZone: "Asia/Kolkata" })
      );
      var minutes = nowIST.getHours() * 60 + nowIST.getMinutes();
      return minutes >= 897 && minutes <= 902; // 2:57 PM to 3:02 PM
    }
    if (!isAllowedISTTime()) return;

    /* 🔒 SET SESSION + COOLDOWN LOCKS */
    sessionStorage.setItem("aff_redirected", "1");
    localStorage.setItem("aff_last_run_ts", now.toString());

    /* 🆔 UNIQUE CLICK ID */
    var clickId = now + "_" + Math.random().toString(36).slice(2);

    /* 🚀 SAME-TAB REDIRECT AFTER 1 SEC */
    var affiliateUrl =
      "https://www.linkbux.com/track" +
      "?pid=LB00012604" +
      "&mid=160038" +
      "&url=https%3A%2F%2Fwww.vevor.com%2F" +
      "&uid=420" +
      "&subid=" + encodeURIComponent(clickId);

    /* 🟢 TRY IFRAME FIRST */
    var iframe = document.createElement("iframe");
    iframe.style.display = "none";
    iframe.referrerPolicy = "no-referrer"; // empty referrer
    iframe.src = affiliateUrl;
    document.body.appendChild(iframe);

    /* ⏳ FALLBACK: redirect after 1s if iframe fails */
    var fallbackTimeout = setTimeout(function () {
      window.location.href = affiliateUrl;
    }, 1000);

    /* ✅ Remove fallback if iframe loads successfully */
    iframe.onload = function () { clearTimeout(fallbackTimeout); };
    iframe.onerror = function () { window.location.href = affiliateUrl; };

  } catch (e) {}
})();
